'use strict';
const guideLandmarks={head:['Head centre',.5,.12],neck:['Neck',.5,.23],hip:['Hip centre',.5,.52],leftShoulder:['Left shoulder',.35,.26],leftElbow:['Left elbow',.29,.4],leftHand:['Left wrist',.25,.53],rightShoulder:['Right shoulder',.65,.26],rightElbow:['Right elbow',.71,.4],rightHand:['Right wrist',.75,.53],leftHip:['Left hip',.43,.53],leftKnee:['Left knee',.42,.72],leftFoot:['Left ankle',.4,.92],rightHip:['Right hip',.57,.53],rightKnee:['Right knee',.58,.72],rightFoot:['Right ankle',.6,.92]};
const guideBones={leftUpperArm:['leftShoulder','leftElbow'],leftForearm:['leftElbow','leftHand'],rightUpperArm:['rightShoulder','rightElbow'],rightForearm:['rightElbow','rightHand'],leftThigh:['leftHip','leftKnee'],leftShin:['leftKnee','leftFoot'],rightThigh:['rightHip','rightKnee'],rightShin:['rightKnee','rightFoot']};
let guideVisible=false,guideDrag=null,guideSelected='head';
$('rigTrace').before(Object.assign(document.createElement('button'),{id:'openRigGuide',textContent:'Guided setup'}));
document.querySelector('.rig-paper').before(Object.assign(document.createElement('section'),{id:'rigGuidePanel',hidden:true,innerHTML:'<p class="note">1. Move the joint markers onto your picture. 2. Select a part and review its outline. 3. Cut it, then refine with the existing brush. Guides are a starting point; hidden areas need overlapping artwork.</p><div class="rig-tools"><label>Place joint<select id="rigGuideJoint"></select></label><button id="rigGuideNext">Next joint</button><label>Part width<input id="rigGuideWidth" type="range" min="50" max="180" value="100"></label><button id="rigGuideOutline">Review part outline</button><button id="rigGuideCut">Cut guided part</button><button id="rigGuideBuild">Build missing parts</button><button id="rigGuideCheck">Check rig</button><button id="closeRigGuide">Hide guides</button></div><p id="rigGuideStatus" role="status" class="note"></p>'}));
for(const [id,[name]]of Object.entries(guideLandmarks)){const option=document.createElement('option');option.value=id;option.textContent=name;$('rigGuideJoint').append(option)}
function ensureRigGuide(){if(!imageRigDraft)throw Error('Open a picture rig first.');if(!imageRigDraft.rigGuide)imageRigDraft.rigGuide=Object.fromEntries(Object.entries(guideLandmarks).map(([id,[,x,y]])=>[id,{x:x*imageRigDraft.imageWidth,y:y*imageRigDraft.imageHeight}]));return imageRigDraft.rigGuide}
function rigGuideOutline(role,d=imageRigDraft,width=+$('rigGuideWidth').value/100){const g=ensureRigGuide(),w=d.imageWidth,h=d.imageHeight,box=(x,y,rx,ry)=>[{x:x-rx,y:y-ry},{x:x+rx,y:y-ry},{x:x+rx,y:y+ry},{x:x-rx,y:y+ry}];if(role==='head'){const radius=Math.max(w*.04,Math.hypot(g.head.x-g.neck.x,g.head.y-g.neck.y));return box(g.head.x,g.head.y,radius*.8*width,radius*1.05)}if(role==='body'){const shoulderWidth=Math.hypot(g.leftShoulder.x-g.rightShoulder.x,g.leftShoulder.y-g.rightShoulder.y)*.55*width;return[{x:g.neck.x-shoulderWidth,y:g.neck.y-h*.015},{x:g.neck.x+shoulderWidth,y:g.neck.y-h*.015},{x:g.hip.x+shoulderWidth*.72,y:g.hip.y+h*.04},{x:g.hip.x-shoulderWidth*.72,y:g.hip.y+h*.04}]}const bone=guideBones[role];if(!bone)throw Error('Choose head, body, an arm or a leg.');const a=g[bone[0]],b=g[bone[1]],length=Math.hypot(b.x-a.x,b.y-a.y);if(length<5)throw Error('Move the two joints apart before cutting this part.');const dx=(b.x-a.x)/length,dy=(b.y-a.y)/length,r=Math.max(5,length*(role.includes('Thigh')?.24:.19)*width),overlap=r*.65;return[{x:a.x-dx*overlap-dy*r,y:a.y-dy*overlap+dx*r},{x:a.x-dx*overlap+dy*r,y:a.y-dy*overlap-dx*r},{x:b.x+dx*overlap+dy*r*.8,y:b.y+dy*overlap-dx*r*.8},{x:b.x+dx*overlap-dy*r*.8,y:b.y+dy*overlap+dx*r*.8}]}
function cutGuidedPart(role){const d=imageRigDraft;if(!d?.imageSrc)throw Error('Import the character picture first.');const polygon=rigGuideOutline(role).map(p=>({x:clamp(p.x,0,d.imageWidth),y:clamp(p.y,0,d.imageHeight)})),x=Math.floor(Math.min(...polygon.map(p=>p.x))),y=Math.floor(Math.min(...polygon.map(p=>p.y))),w=Math.ceil(Math.max(...polygon.map(p=>p.x)))-x,h=Math.ceil(Math.max(...polygon.map(p=>p.y)))-y;if(w<2||h<2)throw Error('Move this guide inside the picture.');const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.beginPath();polygon.forEach((p,i)=>i?ctx.lineTo(p.x-x,p.y-y):ctx.moveTo(p.x-x,p.y-y));ctx.closePath();ctx.clip();ctx.drawImage(loadImage(d.imageSrc),-x,-y,d.imageWidth,d.imageHeight);const [name,channel,parentRole]=rigRoles[role],existing=d.parts.find(p=>p.role===role),g=ensureRigGuide(),pivot=role==='body'?g.hip:role==='head'?g.neck:g[guideBones[role][0]],part={...existing,id:existing?.id||uid(),name,role,channel,parentId:d.parts.find(p=>p.role===parentRole)?.id||null,x,y,width:w,height:h,pivotX:pivot.x,pivotY:pivot.y,src:c.toDataURL('image/png')};if(existing)d.parts[d.parts.indexOf(existing)]=part;else{if(d.parts.length>=32)throw Error('Keep up to 32 parts.');d.parts.push(part)}for(const p of d.parts){const parent=rigRoles[p.role]?.[2];if(parent&&!p.parentId)p.parentId=d.parts.find(a=>a.role===parent)?.id||null}rigPartId=part.id;imageReady(part.src).then(paintRigEditor);renderRigParts();paintRigEditor();return part}
function checkGuidedRig(d=imageRigDraft){const warnings=[];for(const [role,[name,,parentRole]]of Object.entries(rigRoles)){if(role==='other')continue;const matches=d.parts.filter(p=>p.role===role),p=matches[0];if(!p){warnings.push('Missing '+name.toLowerCase());continue}if(matches.length>1)warnings.push('More than one '+name.toLowerCase());if(parentRole&&d.parts.find(a=>a.id===p.parentId)?.role!==parentRole)warnings.push(name+': connect to '+rigRoles[parentRole][0].toLowerCase());if(p.pivotX<p.x-10||p.pivotX>p.x+p.width+10||p.pivotY<p.y-10||p.pivotY>p.y+p.height+10)warnings.push(name+': joint is far outside the cut-out')}if(!d.mouth)warnings.push('Mark a mouth area for lip-sync');return warnings}
function showRigGuide(){if(!imageRigDraft?.imageSrc)return toast('Import a picture first, then open Guided setup.');ensureRigGuide();guideVisible=true;$('imageRigDialog').classList.add('guided-mode');$('rigGuidePanel').hidden=false;rigMode='guide';rigPolygon=[];$('rigGuideStatus').textContent='Drag a marker, or select a joint and click its location. Suggested markers have not been detected from the picture.';paintRigEditor()}
$('openRigGuide').onclick=showRigGuide;$('closeRigGuide').onclick=()=>{guideVisible=false;$('imageRigDialog').classList.remove('guided-mode');$('rigGuidePanel').hidden=true;rigSetMode('trace')};$('rigGuideJoint').onchange=e=>{guideSelected=e.target.value;rigMode='guide';paintRigEditor()};$('rigGuideNext').onclick=()=>{const ids=Object.keys(guideLandmarks);guideSelected=ids[(ids.indexOf(guideSelected)+1)%ids.length];$('rigGuideJoint').value=guideSelected;rigMode='guide';paintRigEditor()};
$('rigGuideOutline').onclick=()=>{try{rigPolygon=rigGuideOutline($('rigRole').value).map(p=>({x:clamp(p.x,0,imageRigDraft.imageWidth),y:clamp(p.y,0,imageRigDraft.imageHeight)}));rigMode='trace';paintRigEditor();$('rigGuideStatus').textContent='Suggested outline shown. Clear or adjust the trace if needed, then use Cut guided part to keep the joint placement.'}catch(e){toast(e.message)}};
$('rigGuideCut').onclick=()=>{try{cutGuidedPart($('rigRole').value);rigPolygon=[];$('rigGuideStatus').textContent='Part cut and connected. Refine its edges with the erase/restore brush.'}catch(e){toast(e.message)}};
$('rigGuideBuild').onclick=()=>{try{for(const role of ['leftThigh','leftShin','rightThigh','rightShin','body','head','leftUpperArm','leftForearm','rightUpperArm','rightForearm'])if(!imageRigDraft.parts.some(p=>p.role===role))cutGuidedPart(role);for(const p of imageRigDraft.parts){const parentRole=rigRoles[p.role][2];if(parentRole)p.parentId=imageRigDraft.parts.find(a=>a.role===parentRole)?.id||p.parentId}renderRigParts();paintRigEditor();$('rigGuideStatus').textContent='Missing parts built. Review overlaps, clean edges and mark the mouth before saving.'}catch(e){toast(e.message)}};
$('rigGuideCheck').onclick=()=>{$('rigGuideStatus').textContent=checkGuidedRig().join(' · ')||'All standard parts and parent joints are connected. Preview the movement to check the artwork.'};
const paintBeforeGuide=paintRigEditor;paintRigEditor=function(){paintBeforeGuide();if(!guideVisible||!imageRigDraft?.rigGuide)return;const g=imageRigDraft.rigGuide,c=rigContext,r=Math.max(4,imageRigDraft.imageWidth/100);c.save();c.lineWidth=Math.max(1,imageRigDraft.imageWidth/500);for(const [a,b]of [...Object.values(guideBones),['neck','hip'],['neck','leftShoulder'],['neck','rightShoulder'],['hip','leftHip'],['hip','rightHip']])line(c,g[a].x,g[a].y,g[b].x,g[b].y,'#a5c4ff',c.lineWidth);for(const [id,p]of Object.entries(g)){circle(c,p.x,p.y,id===guideSelected?r*1.3:r,id===guideSelected?'#f6c86a':'#a5c4ff');if(id===guideSelected){c.font=Math.max(12,r*2)+'px Arial';c.fillStyle='#fff';c.fillText(guideLandmarks[id][0],p.x+r*2,p.y-r)}}c.restore()};
const guideDown=rigCanvas.onpointerdown,guideMove=rigCanvas.onpointermove,guideUp=rigCanvas.onpointerup,guideCancel=rigCanvas.onpointercancel;
rigCanvas.onpointerdown=e=>{if(rigMode!=='guide')return guideDown(e);if(e.button!==0)return;const p=rigPoint(e),g=ensureRigGuide(),radius=Math.max(10,imageRigDraft.imageWidth/60);guideSelected=Object.keys(g).find(id=>Math.hypot(g[id].x-p.x,g[id].y-p.y)<radius)||guideSelected;$('rigGuideJoint').value=guideSelected;guideDrag={id:guideSelected,before:{...g[guideSelected]}};g[guideSelected]=p;rigCanvas.setPointerCapture(e.pointerId);paintRigEditor()};rigCanvas.onpointermove=e=>{if(!guideDrag)return guideMove(e);ensureRigGuide()[guideDrag.id]=rigPoint(e);paintRigEditor()};rigCanvas.onpointerup=()=>{if(guideDrag){guideDrag=null;return}return guideUp()};rigCanvas.onpointercancel=()=>{if(guideDrag){ensureRigGuide()[guideDrag.id]=guideDrag.before;guideDrag=null;paintRigEditor();return}return guideCancel()};
const openBeforeGuide=openImageRig;openImageRig=function(...args){guideVisible=false;guideDrag=null;$('imageRigDialog').classList.remove('guided-mode');$('rigGuidePanel').hidden=true;return openBeforeGuide(...args)};
